import "core-js/modules/esnext.iterator.constructor.js";
import "core-js/modules/esnext.iterator.filter.js";
import "core-js/modules/esnext.iterator.map.js";
import { ref, computed, onMounted, watch } from "vue";
import { db, storage } from "@/firebase";
import { collection, getDocs, query, where, Timestamp, doc, updateDoc, arrayUnion, getDoc } from "firebase/firestore";
import { ref as storageRef, uploadBytes, getDownloadURL } from "firebase/storage";
export default {
  name: "ApprovedPurchases",
  setup() {
    // State variables
    const approvedPurchases = ref([]);
    const loading = ref(true);
    const error = ref(null);
    const searchQuery = ref("");
    const dateFilter = ref("all");
    const sortBy = ref("dateDesc");
    const currentPage = ref(1);
    const itemsPerPage = ref(10);
    const selectedPurchase = ref(null);

    // Bid submission state
    const showBidModal = ref(false);
    const currentPurchaseId = ref(null);
    const bidForm = ref({
      title: "",
      amount: null,
      description: "",
      file: null
    });
    const isSubmitting = ref(false);
    const fileInput = ref(null);

    // Updated fetch function with debug logging
    const fetchApprovedPurchases = async () => {
      loading.value = true;
      error.value = null;
      try {
        console.log("Fetching approved purchases...");

        // Query with capital "A" in "Approved"
        const q = query(collection(db, "purchaseRequests"), where("status", "==", "Approved"));
        console.log("Query created, executing...");
        const querySnapshot = await getDocs(q);
        console.log(`Query returned ${querySnapshot.size} documents`);
        if (querySnapshot.empty) {
          console.log("No approved purchases found");
          approvedPurchases.value = [];
        } else {
          approvedPurchases.value = querySnapshot.docs.map(doc => {
            const data = doc.data();
            console.log("Document data:", data);

            // Generate a request ID if not present
            if (!data.requestId) {
              data.requestId = `PR-${doc.id.substring(0, 6).toUpperCase()}`;
            }

            // Handle Timestamp objects properly
            const createdAt = data.createdAt instanceof Timestamp ? data.createdAt.toDate() : data.createdAt ? new Date(data.createdAt) : new Date();
            const updatedAt = data.updatedAt instanceof Timestamp ? data.updatedAt.toDate() : data.updatedAt ? new Date(data.updatedAt) : new Date();
            const approvalDate = data.approvalDate instanceof Timestamp ? data.approvalDate.toDate() : data.approvalDate ? new Date(data.approvalDate) : updatedAt;
            return {
              id: doc.id,
              ...data,
              itemName: data.itemName || "Unnamed Item",
              category: data.category || "Uncategorized",
              quantity: data.quantity || 0,
              approvedBy: data.approvedBy || "System",
              createdAt: createdAt,
              updatedAt: updatedAt,
              dateApproved: approvalDate,
              bidAttachments: data.bidAttachments || []
            };
          });
          console.log(`Processed ${approvedPurchases.value.length} approved purchases`);
        }
      } catch (err) {
        console.error("Error fetching approved purchases:", err);
        error.value = "Failed to load approved purchases. Please try again.";
      } finally {
        loading.value = false;
      }
    };

    // Format date
    const formatDate = date => {
      if (!date) return "N/A";
      const dateObj = date instanceof Date ? date : new Date(date);
      if (isNaN(dateObj.getTime())) return "Invalid Date";
      return dateObj.toLocaleDateString("en-US", {
        year: "numeric",
        month: "long",
        day: "numeric"
      });
    };

    // Format file size
    const formatFileSize = bytes => {
      if (!bytes) return "0 Bytes";
      const k = 1024;
      const sizes = ["Bytes", "KB", "MB", "GB"];
      const i = Math.floor(Math.log(bytes) / Math.log(k));
      return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + " " + sizes[i];
    };

    // Get bid status text
    const getBidStatusText = purchase => {
      if (!purchase.bidAttachments || purchase.bidAttachments.length === 0) {
        return "No Bids";
      } else if (purchase.bidStatus === "approved") {
        return "Bid Approved";
      } else if (purchase.bidStatus === "rejected") {
        return "Bid Rejected";
      } else {
        return `${purchase.bidAttachments.length} Bid(s)`;
      }
    };

    // Get bid status class
    const getBidStatusClass = purchase => {
      if (!purchase.bidAttachments || purchase.bidAttachments.length === 0) {
        return "no-bids";
      } else if (purchase.bidStatus === "approved") {
        return "bid-approved";
      } else if (purchase.bidStatus === "rejected") {
        return "bid-rejected";
      } else {
        return "bid-pending";
      }
    };

    // Filter purchases based on search query and date filter
    const filteredPurchases = computed(() => {
      let filtered = [...approvedPurchases.value];

      // Apply search filter
      if (searchQuery.value.trim()) {
        const query = searchQuery.value.toLowerCase().trim();
        filtered = filtered.filter(purchase => purchase.itemName?.toLowerCase().includes(query) || purchase.requestId?.toLowerCase().includes(query) || purchase.id.toLowerCase().includes(query));
      }

      // Apply date filter
      if (dateFilter.value !== "all") {
        const now = new Date();
        let startDate;
        switch (dateFilter.value) {
          case "today":
            {
              startDate = new Date(now.setHours(0, 0, 0, 0));
              break;
            }
          case "week":
            {
              startDate = new Date(now.setDate(now.getDate() - now.getDay()));
              break;
            }
          case "month":
            {
              startDate = new Date(now.getFullYear(), now.getMonth(), 1);
              break;
            }
          case "quarter":
            {
              const quarter = Math.floor(now.getMonth() / 3);
              startDate = new Date(now.getFullYear(), quarter * 3, 1);
              break;
            }
          case "year":
            {
              startDate = new Date(now.getFullYear(), 0, 1);
              break;
            }
          default:
            {
              startDate = new Date(0); // Default to epoch start
            }
        }
        filtered = filtered.filter(purchase => {
          const purchaseDate = purchase.dateApproved instanceof Date ? purchase.dateApproved : new Date(purchase.dateApproved || purchase.updatedAt || Date.now());
          return purchaseDate >= startDate;
        });
      }

      // Apply sorting
      filtered.sort((a, b) => {
        switch (sortBy.value) {
          case "dateAsc":
            {
              return new Date(a.dateApproved || a.updatedAt || 0) - new Date(b.dateApproved || b.updatedAt || 0);
            }
          case "dateDesc":
            {
              return new Date(b.dateApproved || b.updatedAt || 0) - new Date(a.dateApproved || a.updatedAt || 0);
            }
          case "nameAsc":
            {
              return (a.itemName || "").localeCompare(b.itemName || "");
            }
          case "nameDesc":
            {
              return (b.itemName || "").localeCompare(a.itemName || "");
            }
          case "quantityAsc":
            {
              return (a.quantity || 0) - (b.quantity || 0);
            }
          case "quantityDesc":
            {
              return (b.quantity || 0) - (a.quantity || 0);
            }
          default:
            {
              return 0;
            }
        }
      });
      return filtered;
    });
    const totalPages = computed(() => {
      return Math.max(1, Math.ceil(filteredPurchases.value.length / itemsPerPage.value));
    });
    const paginatedPurchases = computed(() => {
      const startIndex = (currentPage.value - 1) * itemsPerPage.value;
      const endIndex = startIndex + itemsPerPage.value;
      return filteredPurchases.value.slice(startIndex, endIndex);
    });
    const nextPage = () => {
      if (currentPage.value < totalPages.value) {
        currentPage.value++;
      }
    };
    const prevPage = () => {
      if (currentPage.value > 1) {
        currentPage.value--;
      }
    };

    // Reset to first page when filters change
    watch([searchQuery, dateFilter, sortBy], () => {
      currentPage.value = 1;
    });

    // Handle search
    const handleSearch = () => {
      currentPage.value = 1;
    };

    // Reset filters
    const resetFilters = () => {
      searchQuery.value = "";
      dateFilter.value = "all";
      sortBy.value = "dateDesc";
      currentPage.value = 1;
    };

    // View purchase details
    const viewPurchaseDetails = purchase => {
      selectedPurchase.value = purchase;
    };

    // Close modal
    const closeModal = () => {
      selectedPurchase.value = null;
    };

    // Download PDF
    const downloadPDF = purchase => {
      console.log("Downloading PDF for purchase:", purchase.id);
      alert(`PDF download for ${purchase.itemName} would start here.`);
    };

    // Submit bid
    const submitBid = purchase => {
      currentPurchaseId.value = purchase.id;
      resetBidForm();
      showBidModal.value = true;
    };

    // Close bid modal
    const closeBidModal = () => {
      if (!isSubmitting.value) {
        showBidModal.value = false;
        currentPurchaseId.value = null;
        resetBidForm();
      }
    };

    // Reset bid form
    const resetBidForm = () => {
      bidForm.value = {
        title: "",
        amount: null,
        description: "",
        file: null
      };
    };

    // Trigger file input
    const triggerFileInput = () => {
      fileInput.value.click();
    };

    // Handle file change
    const onFileChange = event => {
      const file = event.target.files[0];
      if (file) {
        bidForm.value.file = file;
      }
    };

    // Handle file drop
    const onFileDrop = event => {
      const file = event.dataTransfer.files[0];
      if (file) {
        bidForm.value.file = file;
      }
    };

    // Remove file
    const removeFile = () => {
      bidForm.value.file = null;
      fileInput.value.value = "";
    };

    // Download attachment
    const downloadAttachment = attachment => {
      if (attachment.fileUrl) {
        window.open(attachment.fileUrl, '_blank');
      } else {
        alert("File URL not available");
      }
    };

    // Submit bid form
    const submitBidForm = async () => {
      if (!bidForm.value.title || !bidForm.value.amount || !bidForm.value.file) {
        alert("Please fill in all required fields and attach a file");
        return;
      }
      isSubmitting.value = true;
      try {
        // Upload file to Firebase Storage
        const fileExt = bidForm.value.file.name.split('.').pop();
        const fileName = `bids/${currentPurchaseId.value}/${Date.now()}.${fileExt}`;
        const fileRef = storageRef(storage, fileName);
        const snapshot = await uploadBytes(fileRef, bidForm.value.file);
        const fileUrl = await getDownloadURL(snapshot.ref);

        // Create bid attachment object
        const bidAttachment = {
          fileName: bidForm.value.file.name,
          fileSize: bidForm.value.file.size,
          fileType: bidForm.value.file.type,
          fileUrl: fileUrl,
          filePath: fileName,
          title: bidForm.value.title,
          amount: parseFloat(bidForm.value.amount),
          description: bidForm.value.description,
          uploadedAt: new Date().toISOString(),
          uploadedBy: "Current User" // Replace with actual user info when available
        };

        // Update purchase document in Firestore
        const purchaseRef = doc(db, "purchaseRequests", currentPurchaseId.value);
        await updateDoc(purchaseRef, {
          bidAttachments: arrayUnion(bidAttachment),
          lastBidDate: new Date().toISOString()
        });

        // Refresh purchase data
        const updatedDoc = await getDoc(purchaseRef);
        if (updatedDoc.exists()) {
          const updatedData = updatedDoc.data();

          // Find and update the purchase in the local array
          const index = approvedPurchases.value.findIndex(p => p.id === currentPurchaseId.value);
          if (index !== -1) {
            approvedPurchases.value[index] = {
              ...approvedPurchases.value[index],
              bidAttachments: updatedData.bidAttachments || [],
              lastBidDate: updatedData.lastBidDate
            };
          }

          // Update selected purchase if it's the current one
          if (selectedPurchase.value && selectedPurchase.value.id === currentPurchaseId.value) {
            selectedPurchase.value = {
              ...selectedPurchase.value,
              bidAttachments: updatedData.bidAttachments || [],
              lastBidDate: updatedData.lastBidDate
            };
          }
        }
        alert("Bid submitted successfully!");
        closeBidModal();
      } catch (error) {
        console.error("Error submitting bid:", error);
        alert("Failed to submit bid. Please try again.");
      } finally {
        isSubmitting.value = false;
      }
    };

    // Fetch data on component mount
    onMounted(fetchApprovedPurchases);
    return {
      approvedPurchases,
      loading,
      error,
      searchQuery,
      dateFilter,
      sortBy,
      currentPage,
      filteredPurchases,
      paginatedPurchases,
      totalPages,
      selectedPurchase,
      showBidModal,
      bidForm,
      isSubmitting,
      fileInput,
      formatDate,
      formatFileSize,
      getBidStatusText,
      getBidStatusClass,
      fetchApprovedPurchases,
      handleSearch,
      resetFilters,
      nextPage,
      prevPage,
      viewPurchaseDetails,
      closeModal,
      downloadPDF,
      submitBid,
      closeBidModal,
      triggerFileInput,
      onFileChange,
      onFileDrop,
      removeFile,
      submitBidForm,
      downloadAttachment
    };
  }
};
